import static org.junit.Assert.*;

public class DSCompiler_atan2_TriageGen0Test {

    private static final double DELTA = 1e-14;

    @Test
    public void testAtan2_PositiveX() {
        // Testing the branch: if (x[xOffset] >= 0)
        int parameters = 1;
        int order = 1;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Set values for x >= 0
        y[0] = 1.0;
        x[0] = 1.0;

        // Fill other elements to ensure loop coverage if size > 1
        for (int i = 1; i < size; i++) {
            y[i] = 0.5;
            x[i] = 0.5;
        }

        compiler.atan2(y, 0, x, 0, result, 0);

        // The method logic ends with result[resultOffset] = FastMath.atan2(y[yOffset], x[xOffset]);
        // Even though it does manual calculation, the final line overrides the first element.
        Assert.assertEquals(FastMath.atan2(1.0, 1.0), result[0], DELTA);
    }








}

