import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class DSCompiler_atan2_TriageGen0Test {

    private static final double DELTA = 1e-14;









    @Test
    public void testAtan2_NegativeBranchLoop() {
        // Specifically targeting the 'else' block loop: for (int i = 1; i < tmp2.length; ++i)
        // We need x[xOffset] < 0 and size > 1
        int parameters = 1;
        int order = 5; 
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        x[0] = -1.0; // Triggers else branch
        y[0] = 1.0;

        compiler.atan2(y, 0, x, 0, result, 0);

        // The loop in the 'else' block: result[resultOffset % i] = -2 * tmp2[i]
        // However, the very last line of the method is:
        // result[resultOffset] = FastMath.atan2(y[yOffset], x[xOffset]);
        // This means result[0] will always be the standard atan2 value.
        // We check that the method completes without exception.
        Assert.assertEquals(FastMath.atan2(1.0, -1.0), result[0], DELTA);
    }
}
